INSERT INTO cars (name,slug,brand,year,body_type,fuel,transmission,price,image_url,badge,description,featured,status) VALUES
('Mercedes-Benz GLC 300 4MATIC','mercedes-benz-glc-300','Mercedes-Benz',2025,'SUV','Xăng','Tự động 9 cấp',2599000000,'https://images.unsplash.com/photo-1618843479313-40f8afb4b4d8?auto=format&fit=crop&w=1200&q=85','Ưu đãi đặc biệt','SUV hạng sang cân bằng giữa sự tinh tế, công nghệ an toàn và cảm giác lái đầy tự tin.',1,'available'),
